import pathlib
import sys
from typing import List


OUTPUT_FILENAME = "processed_data.txt"


def generate_squares(numbers: List[int]) -> List[int]:
    """Generates a list of squares using a list comprehension."""
    if not numbers:
        return []
    return [n**2 for n in numbers]


def format_output_lines(header: str, data: List[int]) -> List[str]:
    """Formats a list of numbers into strings with a header."""
    lines = [f"{header}"]
    lines.extend([f"Item: {item}" for item in data])
    return lines


def write_data_to_file(file_path: pathlib.Path, lines: List[str]) -> None:
    """Writes a list of strings to a file using a context manager."""
    try:
        with file_path.open(mode="w", encoding="utf-8") as f:
            for line in lines:
                f.write(f"{line}\n")
    except OSError as e:
        print(f"Error writing to file {file_path}: {e}", file=sys.stderr)
        raise


def read_numbers_from_file(file_path: pathlib.Path) -> List[int]:
    """Reads numbers from a file, handling potential errors."""
    if not file_path.exists():
        raise FileNotFoundError(f"File not found: {file_path}")

    numbers = []
    with file_path.open(mode="r", encoding="utf-8") as f:
        f.readline()  # Skip header
        for line_num, line in enumerate(f, start=2):
            line = line.strip()
            if not line:
                continue
            try:
                prefix = "Item: "
                if not line.startswith(prefix):
                    raise ValueError("Line format is incorrect")
                numbers.append(int(line[len(prefix) :]))
            except ValueError:
                print(
                    f"Warning: Could not parse line {line_num}: '{line}'",
                    file=sys.stderr,
                )
    return numbers


def main() -> int:
    """Main function to run the data processing script."""
    initial_data = list(range(1, 11))
    print(f"Processing initial data: {initial_data}")

    squared_data = generate_squares(initial_data)
    output_lines = format_output_lines("Squared Numbers", squared_data)

    output_dir = pathlib.Path.cwd() / "output"
    output_dir.mkdir(exist_ok=True)
    file_path = output_dir / OUTPUT_FILENAME

    try:
        write_data_to_file(file_path, output_lines)
        print(f"Successfully wrote data to {file_path}")
    except OSError:
        return 1

    try:
        read_data = read_numbers_from_file(file_path)
        print(f"Successfully read data from file: {read_data}")
        if read_data != squared_data:
            print("Error: Read data does not match written data.", file=sys.stderr)
            return 1
    except (FileNotFoundError, ValueError) as e:
        print(f"Error reading and processing file: {e}", file=sys.stderr)
        return 1

    print("Script completed successfully.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

