@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T

@dataclass(frozen=True)
class Err(Generic[E]):
    message: E

Result = Union[Ok[T], Err[E]]

def parse_int(s: str) -> Result[int, str]:
    """Parses a string into an integer, returning a Result."""
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int, str]:
    """Divides two integers, returning a Result."""
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main() -> None:
