from dataclasses import dataclass
from typing import Self


class Expr:
    pass


@dataclass(frozen=True)
class Num(Expr):
    value: int


@dataclass(frozen=True)
class Add(Expr):
    left: Self
    right: Self


@dataclass(frozen=True)
class Mul(Expr):
    left: Self
    right: Self


def eval_expr(expr: Expr) -> int:
    """Evaluates an expression AST to an integer."""
    match expr:
        case Num(value):
            return value
        case Add(left, right):
            return eval_expr(left) + eval_expr(right)
        case Mul(left, right):
            return eval_expr(left) * eval_expr(right)
        case _:
            raise TypeError(f"Unsupported expression type: {type(expr)}")


