    body_expr: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]
Env = List[Tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for k, v in reversed(env):
        if k == name:
            return v
    raise NameError(f"Unbound variable: {name}")


def eval_expr(expr: Expr, env: Env) -> int:
    match expr:
        case Num(value=value):
            return value
        case Var(name=name):
            return lookup(name, env)
        case Add(left=left, right=right):
            return eval_expr(left, env) + eval_expr(right, env)
        case Mul(left=left, right=right):
            return eval_expr(left, env) * eval_expr(right, env)
        case Let(name=name, value_expr=value_expr, body_expr=body_expr):
            value = eval_expr(value_expr, env)
            return eval_expr(body_expr, env + [(name, value)])
        case _:
            raise TypeError(f"Unknown expression: {expr!r}")


