    Empty => Node(Red, Empty, x, Empty),
    Node(color, left, y, right) =>
      if x < y then
        balance(color, insert_helper(x, left), y, right)
      else if x > y then
        balance(color, left, y, insert_helper(x, right))
      else
        Node(color, left, y, right)
  }

