  match insert_helper(x, tree) {
    Node(_, left, y, right) => Node(Black, left, y, right),
    Empty => Empty
  }

func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, left, value, right) =>
      inorder(left) ++ [value] ++ inorder(right)
  }

func insert_all(values: [int], tree: RBTree) -> RBTree =
  match values {
    [] => tree,
    v :: rest => insert_all(rest, insert(v, tree))
  }

