from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True, slots=True)
class Const:
    value: int

    def __str__(self) -> str:
        return f"Const({self.value})"


@dataclass(frozen=True, slots=True)
class Var:
    name: str

    def __str__(self) -> str:
        return f"Var({self.name})"


@dataclass(frozen=True, slots=True)
class Add:
    left: "Expr"
    right: "Expr"

    def __str__(self) -> str:
        return f"Add({self.left}, {self.right})"


@dataclass(frozen=True, slots=True)
class Mul:
    left: "Expr"
    right: "Expr"

    def __str__(self) -> str:
        return f"Mul({self.left}, {self.right})"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            return Const(1) if name == var else Const(0)
        case Add(left, right):
            return Add(diff(left, var), diff(right, var))
        case Mul(left, right):
            return Add(Mul(left, diff(right, var)), Mul(right, diff(left, var)))
    raise TypeError(f"Unknown expression: {expr!r}")


def simplify(expr: Expr) -> Expr:
    match expr:
        case Const(_) | Var(_):
            return expr
        case Add(left, right):
            left_s = simplify(left)
            right_s = simplify(right)

            if isinstance(left_s, Const) and left_s.value == 0:
                return right_s
            if isinstance(right_s, Const) and right_s.value == 0:
                return left_s

            return Add(left_s, right_s)
        case Mul(left, right):
            left_s = simplify(left)
            right_s = simplify(right)

            if (isinstance(left_s, Const) and left_s.value == 0) or (
                isinstance(right_s, Const) and right_s.value == 0
            ):
                return Const(0)

            if isinstance(left_s, Const) and left_s.value == 1:
                return right_s
            if isinstance(right_s, Const) and right_s.value == 1:
                return left_s

            return Mul(left_s, right_s)
    raise TypeError(f"Unknown expression: {expr!r}")


def main() -> None:
    expr: Expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x")),
        ),
        Const(5),
    )
    derivative = simplify(diff(expr, "x"))
    print(str(derivative))


if __name__ == "__main__":
