    TInt => "TInt",
    TBool => "TBool",
    TFunc(a, r) => "(" ++ showType(a) ++ " -> " ++ showType(r) ++ ")"
  }

func lookupVar(subst: Subst, name: string) -> Type =
  match subst {
    [] => TVar(name),
    s :: rest => if s.varName == name then s.ty else lookupVar(rest, name)
  }

func apply(subst: Subst, t: Type) -> Type =
  match t {
    TVar(name) => lookupVar(subst, name),
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r))
  }

func concatSubst(s1: Subst, s2: Subst) -> Subst =
  match s1 {
    [] => s2,
    x :: rest => x :: concatSubst(rest, s2)
  }

func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TInt => match t2 {
      TInt => Ok([]),
      TVar(b) => Ok([{varName: b, ty: TInt}]),
      _ => Fail
    },
    TBool => match t2 {
      TBool => Ok([]),
      TVar(b) => Ok([{varName: b, ty: TBool}]),
      _ => Fail
    },
    TVar(a) => Ok([{varName: a, ty: t2}]),
    TFunc(a1, r1) => match t2 {
      TVar(b) => Ok([{varName: b, ty: t1}]),
      TFunc(a2, r2) => match unify(a1, a2) {
        Fail => Fail,
        Ok(s1) => match unify(apply(s1, r1), apply(s1, r2)) {
          Fail => Fail,
          Ok(s2) => Ok(concatSubst(s1, s2))
        }
      },
      _ => Fail
    }
  }

